    Control CreateIconPreviewCard(string fileName,string label){var card=new Panel{Size=new Size(105,100),Margin=new Padding(5),BackColor=Color.White,BorderStyle=BorderStyle.FixedSingle};var picture=new PictureBox{Location=new Point(20,5),Size=new Size(64,64),SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.Transparent};string path=Path.Combine(IconDirectory,fileName+".png");try{using(var source=Image.FromFile(path))picture.Image=new Bitmap(source);}catch{}var caption=new Label{Text=label,Location=new Point(3,71),Size=new Size(97,24),TextAlign=ContentAlignment.MiddleCenter,AutoEllipsis=true,ForeColor=Color.FromArgb(35,53,68)};card.Controls.Add(picture);card.Controls.Add(caption);return card;}

