    void InstallArchive(string archivePath,string target,bool iconPack){string staging=target+"-nuevo";if(Directory.Exists(staging))Directory.Delete(staging,true);Directory.CreateDirectory(staging);string safeRoot=Path.GetFullPath(staging)+Path.DirectorySeparatorChar;try{using(var archive=ZipFile.OpenRead(archivePath))foreach(var entry in archive.Entries){string output=Path.GetFullPath(Path.Combine(staging,entry.FullName));if(!output.StartsWith(safeRoot,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("El ZIP contiene una ruta no segura.");if(String.IsNullOrEmpty(entry.Name)){Directory.CreateDirectory(output);continue;}Directory.CreateDirectory(Path.GetDirectoryName(output));entry.ExtractToFile(output,true);}if(iconPack)ValidateIconDirectory(staging,true);else ValidateThemeDirectory(staging,true);string previous=target+"-anterior";if(Directory.Exists(previous))Directory.Delete(previous,true);if(Directory.Exists(target))Directory.Move(target,previous);try{Directory.Move(staging,target);if(Directory.Exists(previous))Directory.Delete(previous,true);}catch{if(Directory.Exists(target))Directory.Delete(target,true);if(Directory.Exists(previous))Directory.Move(previous,target);throw;}}catch{if(Directory.Exists(staging))Directory.Delete(staging,true);throw;}}

    bool ValidateThemeDirectory(string directory,bool throwOnError){var selected=SelectedWindowsTheme;var required=new List<string>{"manifest.json",Path.Combine("Cursors",selected.Prefix+"-arrow.cur"),Path.Combine("Cursors",selected.Prefix+"-working.ani"),Path.Combine("Cursors",selected.Prefix+"-busy.ani"),Path.Combine("Sounds",selected.Prefix+"-notify.wav"),Path.Combine("Sounds",selected.Prefix+"-error.wav")};foreach(string variant in selected.Wallpapers??selected.Variants)required.Add(Path.Combine("DesktopBackground","JANUS-"+selected.FileToken+"-"+variant+"-4K"+selected.WallpaperExtension));if(selected.Slideshow||selected.Id=="newaita"||selected.Id=="papirus"||selected.Id=="retro")foreach(string sound in new[]{"start","logon","logoff","exit"})required.Add(Path.Combine("Sounds",selected.Prefix+"-"+sound+".wav"));foreach(string relative in required)if(!File.Exists(Path.Combine(directory,relative))){if(throwOnError)throw new InvalidDataException("Falta el recurso "+relative+".");return false;}try{string manifest=File.ReadAllText(Path.Combine(directory,"manifest.json"));if(manifest.IndexOf(selected.ManifestId,StringComparison.OrdinalIgnoreCase)<0)throw new InvalidDataException("El manifiesto no corresponde a "+selected.Name+".");return true;}catch{if(throwOnError)throw;return false;}}

    static bool ValidateIconDirectory(string directory,bool throwOnError){foreach(string name in IconNames)foreach(string extension in new[]{".ico",".png"})if(!File.Exists(Path.Combine(directory,name+extension))){if(throwOnError)throw new InvalidDataException("Falta el icono "+name+extension+".");return false;}return true;}

    void PlayPreviewSound(){string file=Path.Combine(ThemeDirectory,"Sounds",SelectedWindowsTheme.Prefix+"-notify.wav");try{if(!File.Exists(file))throw new FileNotFoundException("Carga primero el paquete "+SelectedWindowsTheme.Name+".");using(var player=new SoundPlayer(file)){player.Load();player.Play();}}catch(Exception ex){MessageBox.Show("No se pudo reproducir el sonido:\n"+ex.Message,"Sonido de tema",MessageBoxButtons.OK,MessageBoxIcon.Error);}}

    void ApplySelected(){string themeName=SelectedWindowsTheme.Name,variant=VariantDisplayName(SelectedVariantToken);if(!wallpaper.Checked&&!colors.Checked&&!cursors.Checked&&!sounds.Checked&&!icons.Checked){MessageBox.Show("Selecciona al menos un componente.",themeName,MessageBoxButtons.OK,MessageBoxIcon.Information);return;}if(icons.Checked&&!ValidateIconDirectory(IconDirectory,false)){MessageBox.Show("Carga primero el complemento de iconos o desmarca Iconos.",themeName,MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}string summary="Tema: "+themeName+"\nVariante: "+variant+"\n\nComponentes:\n"+String.Join("\n",SelectedComponentNames().Select(x=>"• "+x));if(MessageBox.Show(summary+"\n\nJANUS guardará el estado actual antes de continuar. ¿Aplicar?","Revisar "+themeName,MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;DualityBackupState state=null;try{state=CaptureState();Directory.CreateDirectory(BackupDirectory);MergeOriginalBackup(state);SaveBackup(Path.Combine(BackupDirectory,"antes-de-aplicar-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json"),state);if(wallpaper.Checked)ApplyWallpaper();if(colors.Checked)ApplyColors();if(cursors.Checked)ApplyCursors();if(sounds.Checked)ApplySounds();if(icons.Checked)ApplyIcons();RegisterWindowsThemes();RefreshWindows();JanusRecovery.Record(themeName,"Aplicar",variant+": "+String.Join(", ",SelectedComponentNames()));RefreshState();MessageBox.Show(themeName+" fue aplicado"+(SelectedWindowsTheme.Slideshow?" y sus fondos rotarán cada 30 minutos.":".")+" Algunos cambios del Explorador pueden terminar de actualizarse al cerrar sesión.",themeName,MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){if(state!=null)try{RestoreState(state);}catch{}MessageBox.Show("No se pudo completar la aplicación y JANUS intentó revertir los cambios parciales:\n"+ex.Message,themeName,MessageBoxButtons.OK,MessageBoxIcon.Error);}}

    IEnumerable<string> SelectedComponentNames(){if(wallpaper.Checked)yield return SelectedWindowsTheme.Slideshow?"Fondos rotativos":"Fondo";if(colors.Checked)yield return "Colores";if(cursors.Checked)yield return "Cursores";if(sounds.Checked)yield return "Sonidos";if(icons.Checked)yield return "Iconos";}

    void RestorePrevious(){if(!File.Exists(OriginalBackup)){MessageBox.Show("No existe un respaldo de tema anterior.","Restaurar tema",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}if(MessageBox.Show("Se restaurarán los valores guardados antes de aplicar el primer tema de JANUS. No se borrarán archivos personales.\n\n¿Continuar?","Restaurar tema anterior",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;try{RestoreState(ReadBackup(OriginalBackup));RefreshWindows();JanusRecovery.Record("Temas de Windows","Restaurar","Tema anterior restaurado");MessageBox.Show("El tema anterior fue restaurado.","Temas de Windows",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show("No se pudo restaurar el tema anterior:\n"+ex.Message,"Temas de Windows",MessageBoxButtons.OK,MessageBoxIcon.Error);}}

    void ApplyWallpaper(){var theme=SelectedWindowsTheme;if(theme.Slideshow){ApplySlideshow(theme);return;}string suffix=SelectedVariantToken;string folder=Path.Combine(ThemeDirectory,"DesktopBackground");string standard=Path.Combine(folder,"JANUS-"+theme.FileToken+"-"+suffix+"-4K"+theme.WallpaperExtension);string ultrawide=Path.Combine(folder,"JANUS-"+theme.FileToken+"-"+suffix+theme.UltrawideSuffix);Rectangle bounds=Screen.PrimaryScreen.Bounds;double ratio=(double)bounds.Width/Math.Max(1,bounds.Height);string selected=ratio>=2.1&&File.Exists(ultrawide)?ultrawide:standard;if(!File.Exists(selected))throw new FileNotFoundException("Falta el fondo "+Path.GetFileName(selected)+".");using(var key=Registry.CurrentUser.CreateSubKey(DesktopKey)){key.SetValue("Wallpaper",selected,RegistryValueKind.String);key.SetValue("WallpaperStyle","10",RegistryValueKind.String);key.SetValue("TileWallpaper","0",RegistryValueKind.String);}if(!SystemParametersInfo(SpiSetDeskWallpaper,0,selected,SpifUpdateIniFile|SpifSendChange))throw new IOException("Windows no aceptó el fondo seleccionado.");}

    void ApplySlideshow(WindowsThemeOption theme){string sourceFolder=Path.Combine(ThemeDirectory,"DesktopBackground"),activeFolder=Path.Combine(ThemeDirectory,"ActiveSlideshow");Directory.CreateDirectory(activeFolder);foreach(string old in Directory.GetFiles(activeFolder))File.Delete(old);Rectangle bounds=Screen.PrimaryScreen.Bounds;bool wide=(double)bounds.Width/Math.Max(1,bounds.Height)>=2.1;foreach(string variant in theme.Wallpapers){string standard=Path.Combine(sourceFolder,"JANUS-"+theme.FileToken+"-"+variant+"-4K"+theme.WallpaperExtension),ultrawide=Path.Combine(sourceFolder,"JANUS-"+theme.FileToken+"-"+variant+theme.UltrawideSuffix),source=wide&&File.Exists(ultrawide)?ultrawide:standard,destination=Path.Combine(activeFolder,Path.GetFileName(source));if(!File.Exists(source))throw new FileNotFoundException("Falta el fondo "+Path.GetFileName(source)+".");if(!CreateHardLink(destination,source,IntPtr.Zero))File.Copy(source,destination,true);}IShellItem folderItem=null;IShellItemArray items=null;IDesktopWallpaper desktop=null;try{Guid itemId=typeof(IShellItem).GUID,arrayId=typeof(IShellItemArray).GUID;Marshal.ThrowExceptionForHR(SHCreateItemFromParsingName(activeFolder,IntPtr.Zero,ref itemId,out folderItem));Marshal.ThrowExceptionForHR(SHCreateShellItemArrayFromShellItem(folderItem,ref arrayId,out items));desktop=(IDesktopWallpaper)new DesktopWallpaperClass();desktop.SetSlideshow(items);desktop.SetSlideshowOptions(1,1800000);desktop.SetPosition(3);}finally{if(desktop!=null)Marshal.FinalReleaseComObject(desktop);if(items!=null)Marshal.FinalReleaseComObject(items);if(folderItem!=null)Marshal.FinalReleaseComObject(folderItem);}}

