        string brand=Path.Combine(ThemeDirectory,"Preview","JANUS-"+theme.FileToken+"-"+variant+"-preview.png");if(File.Exists(brand))lines.Add("BrandImage="+brand);
        if(ValidateIconDirectory(IconDirectory,false)){
          lines.AddRange(new[]{"","[CLSID\\"+ComputerId+"\\DefaultIcon]","DefaultValue="+IconValue("este-equipo"),"","[CLSID\\"+UserFilesId+"\\DefaultIcon]","DefaultValue="+IconValue("archivos-usuario"),"","[CLSID\\"+NetworkId+"\\DefaultIcon]","DefaultValue="+IconValue("red"),"","[CLSID\\"+RecycleId+"\\DefaultIcon]","Full="+IconValue("papelera-llena"),"Empty="+IconValue("papelera-vacia")});
        }
        string cursorsFolder=Path.Combine(ThemeDirectory,"Cursors"),prefix=theme.Prefix;
        lines.AddRange(new[]{"","[Control Panel\\Cursors]","Arrow="+Path.Combine(cursorsFolder,prefix+"-arrow.cur"),"Help="+Path.Combine(cursorsFolder,prefix+"-help.cur"),"AppStarting="+Path.Combine(cursorsFolder,prefix+"-working.ani"),"Wait="+Path.Combine(cursorsFolder,prefix+"-busy.ani"),"NWPen="+Path.Combine(cursorsFolder,prefix+"-pen.cur"),"No="+Path.Combine(cursorsFolder,prefix+"-no.cur"),"SizeNS="+Path.Combine(cursorsFolder,prefix+"-size-ns.cur"),"SizeWE="+Path.Combine(cursorsFolder,prefix+"-size-we.cur"),"Crosshair="+Path.Combine(cursorsFolder,prefix+"-cross.cur"),"IBeam="+Path.Combine(cursorsFolder,prefix+"-ibeam.cur"),"SizeNWSE="+Path.Combine(cursorsFolder,prefix+"-size-nwse.cur"),"SizeNESW="+Path.Combine(cursorsFolder,prefix+"-size-nesw.cur"),"SizeAll="+Path.Combine(cursorsFolder,prefix+"-move.cur"),"UpArrow="+Path.Combine(cursorsFolder,prefix+"-up.cur"),"Hand="+Path.Combine(cursorsFolder,prefix+"-hand.cur"),"DefaultValue="+theme.Name,"","[Control Panel\\Desktop]","Wallpaper="+wallpaperPath,"TileWallpaper=0","WallpaperStyle=10","Pattern=","","[VisualStyles]","Path=%SystemRoot%\\resources\\Themes\\Aero\\Aero.msstyles","ColorStyle=NormalColor","Size=NormalSize","ColorizationColor=0x"+encoded.ToString("X8"),"Transparency=1"});
        string soundsFolder=Path.Combine(ThemeDirectory,"Sounds");var soundFiles=new Dictionary<string,string>{{"Notification.Default",prefix+"-notify.wav"},{"SystemAsterisk",prefix+"-complete.wav"},{"SystemQuestion",prefix+"-question.wav"},{"SystemExclamation",prefix+"-warning.wav"},{"SystemHand",prefix+"-error.wav"}};if(File.Exists(Path.Combine(soundsFolder,prefix+"-logon.wav"))){soundFiles["SystemStart"]=prefix+"-start.wav";soundFiles["WindowsLogon"]=prefix+"-logon.wav";soundFiles["WindowsLogoff"]=prefix+"-logoff.wav";soundFiles["SystemExit"]=prefix+"-exit.wav";}else soundFiles["WindowsLogon"]=prefix+"-start.wav";foreach(var sound in soundFiles){string path=Path.Combine(soundsFolder,sound.Value);if(File.Exists(path))lines.AddRange(new[]{"","[AppEvents\\Schemes\\Apps\\.Default\\"+sound.Key+"]","DefaultValue="+path});}
        lines.AddRange(new[]{"","[MasterThemeSelector]","MTSM=DABJDKT",""});
        string target=Path.Combine(gallery,"JANUS-"+theme.FileToken+"-"+variant+".theme");File.WriteAllLines(target,lines,System.Text.Encoding.Unicode);
      }
      NotifyFolder(gallery);
