    void RegisterWindowsSlideshowTheme(WindowsThemeOption theme,string gallery){string folder=Path.Combine(ThemeDirectory,"DesktopBackground");Rectangle bounds=Screen.PrimaryScreen.Bounds;bool wide=(double)bounds.Width/Math.Max(1,bounds.Height)>=2.1;var wallpapers=new List<string>();foreach(string variant in theme.Wallpapers){string standard=Path.Combine(folder,"JANUS-"+theme.FileToken+"-"+variant+"-4K"+theme.WallpaperExtension),ultrawide=Path.Combine(folder,"JANUS-"+theme.FileToken+"-"+variant+theme.UltrawideSuffix),selected=wide&&File.Exists(ultrawide)?ultrawide:standard;if(File.Exists(selected))wallpapers.Add(selected);}if(wallpapers.Count==0)return;Color color=theme.BaseColor.IsEmpty?theme.LightAccent:theme.BaseColor;uint encoded=unchecked((uint)ColorValue(color));string accentText=theme.LightAccent.R+" "+theme.LightAccent.G+" "+theme.LightAccent.B;var lines=new List<string>{"[Theme]","DisplayName="+theme.Name+" — Colección de fondos","BrandImage="+Path.Combine(ThemeDirectory,"Preview","JANUS-"+theme.FileToken+"-"+theme.Variants[0]+"-preview.png"),"","[Control Panel\\Desktop]","Wallpaper="+wallpapers[0],"TileWallpaper=0","WallpaperStyle=10","Pattern=","","[Control Panel\\Colors]","Hilight="+accentText,"HotTrackingColor="+accentText,"","[Slideshow]","Interval=1800000","Shuffle=1","ImagesRootPath="+folder};for(int i=0;i<wallpapers.Count;i++)lines.Add("Item"+i+"Path="+wallpapers[i]);if(ValidateIconDirectory(IconDirectory,false))lines.AddRange(new[]{"","[CLSID\\"+ComputerId+"\\DefaultIcon]","DefaultValue="+IconValue("este-equipo"),"","[CLSID\\"+UserFilesId+"\\DefaultIcon]","DefaultValue="+IconValue("archivos-usuario"),"","[CLSID\\"+NetworkId+"\\DefaultIcon]","DefaultValue="+IconValue("red"),"","[CLSID\\"+RecycleId+"\\DefaultIcon]","Full="+IconValue("papelera-llena"),"Empty="+IconValue("papelera-vacia")});string cursorsFolder=Path.Combine(ThemeDirectory,"Cursors"),prefix=theme.Prefix;lines.AddRange(new[]{"","[Control Panel\\Cursors]","Arrow="+Path.Combine(cursorsFolder,prefix+"-arrow.cur"),"Help="+Path.Combine(cursorsFolder,prefix+"-help.cur"),"AppStarting="+Path.Combine(cursorsFolder,prefix+"-working.ani"),"Wait="+Path.Combine(cursorsFolder,prefix+"-busy.ani"),"NWPen="+Path.Combine(cursorsFolder,prefix+"-pen.cur"),"No="+Path.Combine(cursorsFolder,prefix+"-no.cur"),"SizeNS="+Path.Combine(cursorsFolder,prefix+"-size-ns.cur"),"SizeWE="+Path.Combine(cursorsFolder,prefix+"-size-we.cur"),"Crosshair="+Path.Combine(cursorsFolder,prefix+"-cross.cur"),"IBeam="+Path.Combine(cursorsFolder,prefix+"-ibeam.cur"),"SizeNWSE="+Path.Combine(cursorsFolder,prefix+"-size-nwse.cur"),"SizeNESW="+Path.Combine(cursorsFolder,prefix+"-size-nesw.cur"),"SizeAll="+Path.Combine(cursorsFolder,prefix+"-move.cur"),"UpArrow="+Path.Combine(cursorsFolder,prefix+"-up.cur"),"Hand="+Path.Combine(cursorsFolder,prefix+"-hand.cur"),"DefaultValue="+theme.Name,"","[VisualStyles]","Path=%SystemRoot%\\resources\\Themes\\Aero\\Aero.msstyles","ColorStyle=NormalColor","Size=NormalSize","ColorizationColor=0x"+encoded.ToString("X8"),"Transparency=1"});string soundsFolder=Path.Combine(ThemeDirectory,"Sounds");foreach(var sound in new Dictionary<string,string>{{"Notification.Default","notify"},{"SystemAsterisk","complete"},{"SystemQuestion","question"},{"SystemExclamation","warning"},{"SystemHand","error"},{"SystemStart","start"},{"WindowsLogon","logon"},{"WindowsLogoff","logoff"},{"SystemExit","exit"}}){string path=Path.Combine(soundsFolder,prefix+"-"+sound.Value+".wav");if(File.Exists(path))lines.AddRange(new[]{"","[AppEvents\\Schemes\\Apps\\.Default\\"+sound.Key+"]","DefaultValue="+path});}lines.AddRange(new[]{"","[MasterThemeSelector]","MTSM=DABJDKT",""});File.WriteAllLines(Path.Combine(gallery,"JANUS-"+theme.FileToken+".theme"),lines,System.Text.Encoding.Unicode);}

    void ApplyColors(){bool dark=SelectedVariantUsesDarkMode;var theme=SelectedWindowsTheme;if(!theme.PreserveMode){SetDword(PersonalizeKey,"AppsUseLightTheme",dark?0:1);SetDword(PersonalizeKey,"SystemUsesLightTheme",dark?0:1);}SetDword(PersonalizeKey,"ColorPrevalence",1);int accent=ColorValue(AccentForVariant(theme,SelectedVariantToken)),baseColor=theme.BaseColor.IsEmpty?accent:ColorValue(theme.BaseColor);SetDword(DwmKey,"ColorizationColor",baseColor);SetDword(DwmKey,"ColorPrevalence",1);SetDword(AccentKey,"AccentColorMenu",accent);BroadcastSetting("ImmersiveColorSet");}

    void ApplyCursors(){var theme=SelectedWindowsTheme;string folder=Path.Combine(ThemeDirectory,"Cursors"),prefix=theme.Prefix;var values=new Dictionary<string,string>{{"Arrow",prefix+"-arrow.cur"},{"Help",prefix+"-help.cur"},{"AppStarting",prefix+"-working.ani"},{"Wait",prefix+"-busy.ani"},{"Crosshair",prefix+"-cross.cur"},{"IBeam",prefix+"-ibeam.cur"},{"NWPen",prefix+"-pen.cur"},{"No",prefix+"-no.cur"},{"SizeNS",prefix+"-size-ns.cur"},{"SizeWE",prefix+"-size-we.cur"},{"SizeNWSE",prefix+"-size-nwse.cur"},{"SizeNESW",prefix+"-size-nesw.cur"},{"SizeAll",prefix+"-move.cur"},{"UpArrow",prefix+"-up.cur"},{"Hand",prefix+"-hand.cur"}};using(var key=Registry.CurrentUser.CreateSubKey(CursorsKey)){key.SetValue("",theme.Name,RegistryValueKind.String);key.SetValue("Scheme Source",1,RegistryValueKind.DWord);foreach(var item in values){string path=Path.Combine(folder,item.Value);if(!File.Exists(path))throw new FileNotFoundException("Falta el cursor "+item.Value+".");key.SetValue(item.Key,path,RegistryValueKind.String);}}if(!SystemParametersInfo(SpiSetCursors,0,null,SpifSendChange))throw new IOException("Windows no pudo actualizar el esquema de cursores.");}

    void ApplySounds(){var theme=SelectedWindowsTheme;string folder=Path.Combine(ThemeDirectory,"Sounds"),prefix=theme.Prefix;var events=new Dictionary<string,string>{{"Notification.Default",prefix+"-notify.wav"},{"SystemAsterisk",prefix+"-complete.wav"},{"SystemQuestion",prefix+"-question.wav"},{"SystemExclamation",prefix+"-warning.wav"},{"SystemHand",prefix+"-error.wav"}};string start=Path.Combine(folder,prefix+"-start.wav"),logon=Path.Combine(folder,prefix+"-logon.wav");if(File.Exists(logon)){events["SystemStart"]=prefix+"-start.wav";events["WindowsLogon"]=prefix+"-logon.wav";events["WindowsLogoff"]=prefix+"-logoff.wav";events["SystemExit"]=prefix+"-exit.wav";}else events["WindowsLogon"]=prefix+"-start.wav";using(var scheme=Registry.CurrentUser.CreateSubKey(SchemesKey))scheme.SetValue("",theme.Name,RegistryValueKind.String);foreach(var item in events){string file=Path.Combine(folder,item.Value);if(!File.Exists(file))throw new FileNotFoundException("Falta el sonido "+item.Value+".");using(var key=Registry.CurrentUser.CreateSubKey(SoundEventKey(item.Key)))key.SetValue("",file,RegistryValueKind.String);}BroadcastSetting("Sound");}

    void ApplyIcons(){Directory.CreateDirectory(IconDirectory);string computer=IconValue("este-equipo"),user=IconValue("archivos-usuario"),network=IconValue("red"),empty=IconValue("papelera-vacia"),full=IconValue("papelera-llena");SetIconValue(ComputerId,"",computer);SetIconValue(UserFilesId,"",user);SetIconValue(NetworkId,"",network);foreach(string keyPath in IconKeyPaths(RecycleId))using(var key=Registry.CurrentUser.CreateSubKey(keyPath)){key.SetValue("",empty,RegistryValueKind.String);key.SetValue("empty",empty,RegistryValueKind.String);key.SetValue("full",full,RegistryValueKind.String);}foreach(var folder in KnownFolders()){ApplyFolderIcon(folder.Item2,folder.Item3,folder.Item4);}foreach(var drive in DriveInfo.GetDrives()){if(!drive.IsReady)continue;string icon=drive.DriveType==DriveType.Removable?IconValue("usb"):drive.DriveType==DriveType.Network?IconValue("unidad-red"):IconValue("hdd-ssd");foreach(string keyPath in DriveIconKeys(drive.Name))using(var key=Registry.CurrentUser.CreateSubKey(keyPath))key.SetValue("",icon,RegistryValueKind.String);}}

    string IconValue(string name){string file=Path.Combine(IconDirectory,name+".ico");if(!File.Exists(file))throw new FileNotFoundException("Falta el icono "+name+".ico.");return file+",0";}
    static void SetIconValue(string id,string name,string value){foreach(string path in IconKeyPaths(id))using(var key=Registry.CurrentUser.CreateSubKey(path))key.SetValue(name,value,RegistryValueKind.String);}
    static IEnumerable<string> IconKeyPaths(string id){yield return @"Software\Microsoft\Windows\CurrentVersion\Explorer\CLSID\"+id+@"\DefaultIcon";yield return @"Software\Classes\CLSID\"+id+@"\DefaultIcon";}
    static IEnumerable<string> DriveIconKeys(string driveName){string letter=driveName.Substring(0,1).ToUpperInvariant();yield return @"Software\Microsoft\Windows\CurrentVersion\Explorer\DriveIcons\"+letter+@"\DefaultIcon";yield return @"Software\Classes\Applications\Explorer.exe\Drives\"+letter+@"\DefaultIcon";}
    static string SoundEventKey(string eventName){return @"AppEvents\Schemes\Apps\.Default\"+eventName+@"\.Current";}
    static string QuickAccessKey(string id){return @"Software\Classes\CLSID\"+id+@"\DefaultIcon";}
    static readonly string[] IconNames={"este-equipo","archivos-usuario","red","papelera-vacia","papelera-llena","documentos","descargas","escritorio","imagenes","musica","videos","hdd-ssd","usb","unidad-red"};

    static IEnumerable<Tuple<string,string,string,string>> KnownFolders(){yield return Tuple.Create("Documentos",Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"documentos", "{FDD39AD0-238F-46AF-ADB4-6C85480369C7}");yield return Tuple.Create("Descargas",Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads"),"descargas","{374DE290-123F-4565-9164-39C4925E467B}");yield return Tuple.Create("Escritorio",Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"escritorio","{B4BFCC3A-DB2C-424C-B029-7FE99A87C641}");yield return Tuple.Create("Imágenes",Environment.GetFolderPath(Environment.SpecialFolder.MyPictures),"imagenes","{33E28130-4E1E-4676-835A-98395C3BC3BB}");yield return Tuple.Create("Música",Environment.GetFolderPath(Environment.SpecialFolder.MyMusic),"musica","{4BD8D571-6D19-48D3-BE97-422220080E43}");yield return Tuple.Create("Vídeos",Environment.GetFolderPath(Environment.SpecialFolder.MyVideos),"videos","{18989B1D-99B5-455B-841C-AB7C74E4DDFC}");}

    void ApplyFolderIcon(string path,string iconName,string quickAccessId){if(!Directory.Exists(path))return;string ini=Path.Combine(path,"desktop.ini");if(!WritePrivateProfileString(".ShellClassInfo","IconResource",IconValue(iconName),ini))throw new IOException("Windows no permitió cambiar el icono de "+path+".");File.SetAttributes(ini,FileAttributes.Hidden|FileAttributes.System);File.SetAttributes(path,File.GetAttributes(path)|FileAttributes.ReadOnly);SetIconValue(quickAccessId,"",IconValue(iconName));NotifyFolder(path);}

    DualityBackupState CaptureState(){var state=new DualityBackupState{CreatedUtc=DateTime.UtcNow,Registry=new Dictionary<string,Dictionary<string,DualityRegistryValueState>>(),Folders=new List<DualityFolderState>()};if(wallpaper.Checked)AddCapture(state,DesktopKey,new[]{"Wallpaper","WallpaperStyle","TileWallpaper"});if(colors.Checked){AddCapture(state,PersonalizeKey,new[]{"AppsUseLightTheme","SystemUsesLightTheme","ColorPrevalence"});AddCapture(state,DwmKey,new[]{"ColorizationColor","ColorPrevalence"});AddCapture(state,AccentKey,new[]{"AccentColorMenu"});}if(cursors.Checked)AddCapture(state,CursorsKey,new[]{"","Scheme Source","Arrow","Help","AppStarting","Wait","Crosshair","IBeam","NWPen","No","SizeNS","SizeWE","SizeNWSE","SizeNESW","SizeNWSE","SizeAll","UpArrow","Hand"});if(sounds.Checked){AddCapture(state,SchemesKey,new[]{""});foreach(string eventName in new[]{"Notification.Default","SystemAsterisk","SystemQuestion","SystemExclamation","SystemHand","SystemStart","WindowsLogon","WindowsLogoff","SystemExit"})AddCapture(state,SoundEventKey(eventName),new[]{""});}if(icons.Checked){foreach(string id in new[]{ComputerId,UserFilesId,NetworkId})foreach(string path in IconKeyPaths(id))AddCapture(state,path,new[]{""});foreach(string path in IconKeyPaths(RecycleId))AddCapture(state,path,new[]{"","empty","full"});foreach(var folder in KnownFolders()){foreach(string path in IconKeyPaths(folder.Item4))AddCapture(state,path,new[]{""});if(Directory.Exists(folder.Item2)){string ini=Path.Combine(folder.Item2,"desktop.ini");state.Folders.Add(new DualityFolderState{Path=folder.Item2,IniExists=File.Exists(ini),IniBase64=File.Exists(ini)?Convert.ToBase64String(File.ReadAllBytes(ini)):null,IniAttributes=File.Exists(ini)?(int)File.GetAttributes(ini):0,FolderAttributes=(int)File.GetAttributes(folder.Item2)});}}foreach(var drive in DriveInfo.GetDrives())if(drive.IsReady)foreach(string path in DriveIconKeys(drive.Name))AddCapture(state,path,new[]{""});}return state;}

    static void MergeOriginalBackup(DualityBackupState current){if(!File.Exists(OriginalBackup)){SaveBackup(OriginalBackup,current);return;}var original=ReadBackup(OriginalBackup);if(original.Registry==null)original.Registry=new Dictionary<string,Dictionary<string,DualityRegistryValueState>>();foreach(var key in current.Registry){if(!original.Registry.ContainsKey(key.Key))original.Registry[key.Key]=key.Value;else foreach(var value in key.Value)if(!original.Registry[key.Key].ContainsKey(value.Key))original.Registry[key.Key][value.Key]=value.Value;}if(original.Folders==null)original.Folders=new List<DualityFolderState>();foreach(var folder in current.Folders)if(!original.Folders.Any(x=>String.Equals(x.Path,folder.Path,StringComparison.OrdinalIgnoreCase)))original.Folders.Add(folder);SaveBackup(OriginalBackup,original);}

    static void AddCapture(DualityBackupState state,string path,IEnumerable<string> names){var values=new Dictionary<string,DualityRegistryValueState>();using(var key=Registry.CurrentUser.OpenSubKey(path))foreach(string name in names){object value=key==null?null:key.GetValue(name,null,RegistryValueOptions.DoNotExpandEnvironmentNames);if(value==null)values[name]=new DualityRegistryValueState{Exists=false};else{RegistryValueKind kind=key.GetValueKind(name);values[name]=new DualityRegistryValueState{Exists=true,Kind=(int)kind,Data=SerializeValue(value,kind)};}}state.Registry[path]=values;}
    static string SerializeValue(object value,RegistryValueKind kind){if(kind==RegistryValueKind.Binary)return Convert.ToBase64String((byte[])value);if(kind==RegistryValueKind.MultiString)return String.Join("\u0000",(string[])value);return Convert.ToString(value,System.Globalization.CultureInfo.InvariantCulture);}
    static object DeserializeValue(DualityRegistryValueState state){RegistryValueKind kind=(RegistryValueKind)state.Kind;if(kind==RegistryValueKind.Binary)return Convert.FromBase64String(state.Data);if(kind==RegistryValueKind.MultiString)return state.Data.Split(new[]{'\u0000'},StringSplitOptions.None);if(kind==RegistryValueKind.DWord)return Int32.Parse(state.Data,System.Globalization.CultureInfo.InvariantCulture);if(kind==RegistryValueKind.QWord)return Int64.Parse(state.Data,System.Globalization.CultureInfo.InvariantCulture);return state.Data??"";}
    static void SaveBackup(string path,DualityBackupState state){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,new JavaScriptSerializer().Serialize(state),System.Text.Encoding.UTF8);}
    static DualityBackupState ReadBackup(string path){return new JavaScriptSerializer().Deserialize<DualityBackupState>(File.ReadAllText(path,System.Text.Encoding.UTF8));}

    static void RestoreState(DualityBackupState state){foreach(var keyState in state.Registry){using(var key=Registry.CurrentUser.CreateSubKey(keyState.Key))foreach(var value in keyState.Value){if(!value.Value.Exists)key.DeleteValue(value.Key,false);else key.SetValue(value.Key,DeserializeValue(value.Value),(RegistryValueKind)value.Value.Kind);}}foreach(var folder in state.Folders){if(!Directory.Exists(folder.Path))continue;string ini=Path.Combine(folder.Path,"desktop.ini");try{if(File.Exists(ini))File.SetAttributes(ini,FileAttributes.Normal);if(folder.IniExists){File.WriteAllBytes(ini,Convert.FromBase64String(folder.IniBase64));File.SetAttributes(ini,(FileAttributes)folder.IniAttributes);}else if(File.Exists(ini))File.Delete(ini);File.SetAttributes(folder.Path,(FileAttributes)folder.FolderAttributes);NotifyFolder(folder.Path);}catch{}}if(state.Registry.ContainsKey(DesktopKey)&&state.Registry[DesktopKey].ContainsKey("Wallpaper")){var saved=state.Registry[DesktopKey]["Wallpaper"];SystemParametersInfo(SpiSetDeskWallpaper,0,saved.Exists?saved.Data:"",SpifUpdateIniFile|SpifSendChange);}if(state.Registry.ContainsKey(CursorsKey))SystemParametersInfo(SpiSetCursors,0,null,SpifSendChange);}

    static void SetDword(string path,string name,int value){using(var key=Registry.CurrentUser.CreateSubKey(path))key.SetValue(name,value,RegistryValueKind.DWord);}
    static int ColorValue(Color color){return unchecked((int)(0xFF000000u|((uint)color.B<<16)|((uint)color.G<<8)|color.R));}
    static void RefreshWindows(){BroadcastSetting("WindowsThemeElement");SHChangeNotify(0x08000000,0x1000,IntPtr.Zero,IntPtr.Zero);try{Process.Start(new ProcessStartInfo("ie4uinit.exe","-show"){UseShellExecute=false,CreateNoWindow=true});}catch{}}
    static void BroadcastSetting(string section){IntPtr result;SendMessageTimeout(new IntPtr(0xffff),0x001A,IntPtr.Zero,section,0x0002,1500,out result);}
    static void NotifyFolder(string folder){SHChangeNotifyPath(0x00002000,0x1005,folder,IntPtr.Zero);string parent=Path.GetDirectoryName(folder);if(!String.IsNullOrWhiteSpace(parent))SHChangeNotifyPath(0x00001000,0x1005,parent,IntPtr.Zero);}

